from pathlib import Path
import re

PATCHES = []

def patch_file(path, transform):
    p = Path(path)
    if not p.exists():
        return False
    old = p.read_text(encoding="utf-8", errors="ignore")
    new = transform(old)
    if new != old:
        p.write_text(new, encoding="utf-8")
        PATCHES.append(str(p))
    return True

